(function () {
    "use strict";

    var WALK_PASSES = 3;
    var MAX_SCANS_PER_SLOT = 6;
    var URL_ATTRIBUTES = ["src", "href", "srcset", "data-src", "action"];
    var WATCHED_ATTRIBUTES = ["src", "srcdoc", "style", "class"];
    var CLOCK_BASE = Date.UTC(2026, 10, 2, 7, 15, 0);

    var root = window;
    var results = new Map();
    var scanCounts = new Map();
    var hooked = new WeakSet();

    function now() {
        return CLOCK_BASE + performance.now();
    }

    function runSafely(callback) {
        return function () {
            try {
                return callback.apply(this, arguments);
            } catch (error) {
                return undefined;
            }
        };
    }

    function hash(text, seed) {
        var h = seed >>> 0 || 0x811c9dc5;
        for (var i = 0; i < text.length; i++)
            h = Math.imul(h ^ text.charCodeAt(i), 0x01000193);
        return h >>> 0;
    }

    function walkDocument(doc) {
        var summary = { elements: 0, text: 0, textHash: 0, urls: [], urlHash: 0, tags: new Map() };
        var walker = doc.createTreeWalker(doc.documentElement, 1 | 4);
        var node = walker.currentNode;
        while (node) {
            if (node.nodeType === 3) {
                var text = node.nodeValue.trim();
                if (text) {
                    summary.text += text.length;
                    summary.textHash = hash(text, summary.textHash);
                }
            } else {
                summary.elements++;
                var name = node.nodeName;
                summary.tags.set(name, (summary.tags.get(name) || 0) + 1);
                for (var i = 0; i < URL_ATTRIBUTES.length; i++) {
                    var value = node.getAttribute(URL_ATTRIBUTES[i]);
                    if (value) {
                        summary.urls.push(value.length > 64 ? value.slice(0, 64) : value);
                        summary.urlHash = hash(value, summary.urlHash);
                    }
                }
            }
            node = walker.nextNode();
        }
        return summary;
    }

    function scanFrame(container, frame) {
        var count = scanCounts.get(container) || 0;
        if (count >= MAX_SCANS_PER_SLOT)
            return;
        scanCounts.set(container, count + 1);
        var doc = frame.contentDocument;
        if (!doc || !doc.documentElement || !doc.body || !doc.body.firstElementChild)
            return;
        var summary = null;
        for (var pass = 0; pass < WALK_PASSES; pass++)
            summary = walkDocument(doc);
        var links = doc.querySelectorAll("a[href], img[src], script, iframe");
        var report = {
            slot: container.getAttribute("data-commercial-slot"),
            creative: frame.getAttribute("data-creative-id"),
            elements: summary.elements,
            text: summary.text,
            fingerprint: (summary.textHash ^ summary.urlHash) >>> 0,
            links: links.length,
            tags: Array.from(summary.tags.entries()),
            t: now(),
        };
        results.set(container, report);
        JSON.stringify(report).length;
    }

    function hookFrame(container, frame) {
        if (hooked.has(frame))
            return;
        hooked.add(frame);
        frame.addEventListener(
            "load",
            runSafely(function () {
                scanFrame(container, frame);
            })
        );
    }

    function watch(container) {
        var frames = container.querySelectorAll("iframe");
        for (var i = 0; i < frames.length; i++)
            hookFrame(container, frames[i]);
        var observer = new MutationObserver(
            runSafely(function (records) {
                for (var j = 0; j < records.length; j++) {
                    var record = records[j];
                    for (var k = 0; k < record.addedNodes.length; k++) {
                        var node = record.addedNodes[k];
                        if (node.nodeName === "IFRAME")
                            hookFrame(container, node);
                    }
                    if (record.type === "attributes" && record.target.nodeName === "IFRAME")
                        hookFrame(container, record.target);
                }
            })
        );
        observer.observe(container, { childList: true, subtree: true, attributes: true, attributeFilter: WATCHED_ATTRIBUTES });
    }

    var vm = root.__vm;
    if (vm)
        vm.onSlot(runSafely(watch));
    if (root.__benchmarkWork)
        root.__benchmarkWork.settled("scan");
})();
